window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["37"]={"https://www.gov.uk/foreign-travel-advice/benin":{"r":"govuk","at":"2026-11-17T16:16Z","sha":"50bcf08f25ff1bcd89378a421fa65d1fe5b614ed01dba118cf7c7fb8ee285563","read":"https://www.gov.uk/api/content/foreign-travel-advice/benin","bytes":51619,"x":"fulltext v1","title":"Benin travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-03-18T14:57:17+00:00","mod":"2026-11-04T16:27:24+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth and Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against travel"]},{"k":"hs","s":["Northern border regions"]},{"k":"p","s":["FCDO advises against all travel to the Parc du W National Park and the hunting zones of Mékrou and Djona. The park is tri-national, sharing an open border with Burkina Faso and Niger. There is a risk of terrorist attacks and kidnapping throughout the park."]},{"k":"p","s":["FCDO also advises against all travel to:"]},{"k":"li","s":["the area between the Parc du W and the border with Niger"]},{"k":"li","s":["the Pendjari National Park and adjacent hunting grounds"]},{"k":"li","s":["all other areas within 5km of the border with Burkina Faso"]},{"k":"hs","s":["Eastern Benin"]},{"k":"p","s":["FCDO advises against all but essential travel to the area between the Interstate Highway (RNIE) 2 from Tchaourou to Malanville and the Benin-Nigeria border, due to increasing criminality."]},{"k":"hs","s":["Alibori and Atacora"]},{"k":"p","s":["FCDO advises against all but essential travel to the rest of the Alibori and Atacora departments."]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/benin/regional-risks"],"."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/benin/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Benin’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Benin set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Beninese Embassy in France","https://www.benin-ambassade.fr/"]," (in French)."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["Your passport must be valid for the duration of your stay."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to enter or travel through Benin."]},{"k":"p","s":["For further information on entry requirements, contact the ",["Beninese Embassy in France","https://www.benin-ambassade.fr/"]," (in French)."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":[["Apply for a Benin visa online","https://evisa.bj/"]," at least 4 working days before your arrival date. You will receive your e-visa by email."]},{"k":"hs","s":["Visas for Nigeria, Ghana and Togo"]},{"k":"p","s":["You cannot get entry visas for Nigeria, Ghana or Togo in Benin. For onward travel you must apply for visas before travelling to Benin."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To enter Benin, you must have a certificate to prove you’ve had a yellow fever vaccination."]},{"k":"p","s":["For more details about health entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Benin guide","https://travelhealthpro.org.uk/country/27/benin#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Benin","https://douanes.gouv.bj/"]," (in French). You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Benin"]},{"k":"p","s":["Terrorists are very likely to try to carry out attacks in Benin."]},{"k":"p","s":["Attacks could be indiscriminate, including in places visited by foreign nationals such as:"]},{"k":"li","s":["beach resorts"]},{"k":"li","s":["hotels"]},{"k":"li","s":["bars"]},{"k":"li","s":["restaurants"]},{"k":"p","s":["Stay aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"p","s":["There is a risk of terrorist attacks in the northern border regions, including throughout the Parc du W National Park, which is tri-national and shares an open border between Benin, Burkina Faso and Niger. Recent incidents in the region have targeted military bases and security installations. See ",["Regional risks","https://www.gov.uk/foreign-travel-advice/benin/regional-risks"],"."]},{"k":"p","s":["Examples of recent significant attacks include:"]},{"k":"li","s":["in April 2025, 54 soldiers were killed in an attack against two military posts in Parc du W National Park"]},{"k":"li","s":["in January 2025, 28 soldiers were killed in an attack against a military post in Parc du W National Park"]},{"k":"li","s":["in 2022, 7 national park staff and 1 military personnel were killed and 12 people were injured when 2 separate vehicle convoys hit improvised explosive devices in the Beninese side of the Parc National du W"]},{"k":"li","s":["in 2021, at least 2 people were killed in an attack in the northern border area of Porga"]},{"k":"hs","s":["Terrorist kidnap"]},{"k":"p","s":["Foreigners, government officials and civilians have been kidnapped by groups originating in bordering countries including Niger and Burkina Faso. Groups include Al-Qaida in the Islamic Maghreb (AQIM) and Jamaat Nusrat al-Islam wal Muslimeen (JNIM), who may travel across the region’s porous borders. There is a heightened risk of kidnap in areas bordering the Sahel, this includes northern Benin."]},{"k":"p","s":["In 2019, 2 French tourists and their Beninese guide were kidnapped from Pendjari National Park. The guide was found dead, but the hostages were rescued in Burkina Faso a few days later."]},{"k":"p","s":["British nationals are seen as legitimate targets, including tourists, humanitarian aid workers, journalists and business travellers. If you are kidnapped, the reason for your presence is unlikely to protect you or secure your safe release."]},{"k":"p","s":["The long-standing policy of the British government is to not make substantive concessions to hostage takers. The British government considers that paying ransoms and releasing prisoners builds the capability of terrorist groups and finances their activities. This can, in turn, increase the risk of further hostage-taking. The Terrorism Act (2000) makes payments to terrorists illegal."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["Political demonstrations and unrest can occur without warning. Benin experienced an attempted coup on 7 December. Avoid all demonstrations, large crowds, political gatherings and rallies. In the event of unrest, monitor local media and follow instructions and announcements from the local authorities. Comply with any checks or security measures, including curfews. The authorities may introduce these at short notice."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Street crime"]},{"k":"p","s":["Street crime, including theft and mugging, is common in Cotonou. Pickpockets often operate in places visited by international travellers."]},{"k":"p","s":["To reduce your personal risk:"]},{"k":"li","s":["take care in crowded areas, including hotels, bars and on public transport"]},{"k":"li","s":["avoid walking alone at night and in isolated areas"]},{"k":"li","s":["be alert in Grand Marché de Dantokpa (Dantokpa Market) and avoid the area at night"]},{"k":"li","s":["do not walk on the beach alone at any time"]},{"k":"li","s":["in general do not resist an armed attacker"]},{"k":"hs","s":["Vehicle crime"]},{"k":"p","s":["Be alert to the risk of carjacking both in Cotonou and on roads outside towns and cities. Always keep doors locked and windows closed when driving and avoid driving after dark. Do not slow down or stop if people signal you to pull over."]},{"k":"hs","s":["Scams"]},{"k":"p","s":["Scam artists target foreign visitors and residents. The scams come in many forms – romance and friendship, business ventures, work and employment opportunities – and can cause great financial loss. Warn your friends and family to be sceptical if they’re asked to transfer funds to you in Benin. Tell them to contact you to check that you’ve made this request."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Voodoo culture"]},{"k":"p","s":["Benin is one of the main centres of Voodoo practices, and Voodoo culture is prevalent. You should research and respect religious and social traditions to avoid offending local sensitivities."]},{"k":"p","s":["Most people in Benin celebrate Voodoo Festival, an annual public holiday in early January. Make sure you’ve arranged travel and accommodation as options are limited during the festival. Watch out for pickpockets."]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Possession, use or trafficking of illegal drugs is a serious offence and can result in a lengthy prison sentence and heavy fines."]},{"k":"hs","s":["Using cameras in secure areas"]},{"k":"p","s":["It is illegal to take photos at or near sensitive or government sites, such as military installations or the airport."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex sexual activity is legal, but same-sex relationships are not widely accepted. Showing affection in public can receive negative attention."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Bribes"]},{"k":"p","s":["You should politely and firmly decline requests for ‘gifts’ from officials to facilitate administrative matters as this could implicate you in illegal activity."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"hs","s":["Swimming safety"]},{"k":"p","s":["Ocean currents are very strong along all parts of the coast. Many drownings occur each year. Do not swim unless you have reliable local advice and confidence in your ability. See ",["water safety on holiday","https://www.rlss.org.uk/safety-on-holiday"]," from the Royal Life Saving Society."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Benin, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You’ll need to have both the ",["correct version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," and your UK driving licence with you in the car."]},{"k":"p","s":["Driving standards and road conditions in Benin are poor. Avoid driving outside towns and cities at night as roads are poorly lit. During the rainy seasons there may be flooding, particularly in rural areas."]},{"k":"p","s":["Fuel shortages are common in rural areas of northern Benin. Police sometimes check vehicles at temporary roadblocks to improve road safety and reduce the number of carjackings."]},{"k":"p","s":["There’s no reliable public transport in Benin. Avoid using taxis and long-distance buses as they’re poorly maintained and often overloaded."]},{"k":"hs","s":["Sea travel"]},{"k":"p","s":["Piracy is a risk in the Gulf of Guinea, including in ports across the region. Take precautions to avoid ",["piracy and armed robbery at sea","https://www.gov.uk/guidance/sea-river-and-piracy-safety"],"."]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Benin. It only covers regions where the Foreign, Commonwealth & Development Office (FCDO) has specific advice."]},{"k":"p","s":["You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/benin"]," and ",["safety and security advice","https://www.gov.uk/foreign-travel-advice/benin/safety-and-security"],"."]},{"k":"h","s":["Northern border regions"]},{"k":"p","s":["FCDO advises against all travel to the Parc du W National Park and the connecting hunting zones of Meêkrou and Djona. The park is tri-national, sharing an open border with Burkina Faso and Niger. There is a risk of terrorist attacks throughout the park."]},{"k":"p","s":["FCDO also advises against all travel to:"]},{"k":"li","s":["the area between the Parc du W and the border with Niger"]},{"k":"li","s":["the Pendjari National Park and adjacent hunting grounds"]},{"k":"li","s":["all other areas within 5km of the border with Burkina Faso"]},{"k":"p","s":["There is a threat of kidnapping from terrorist groups operating in the region. There is a heightened risk of kidnap in Benin’s northern border region."]},{"k":"p","s":["The authorities sometimes set curfews in northern Benin. Keep up to date with security measures and follow the advice of the local security authorities."]},{"k":"h","s":["Eastern Benin"]},{"k":"p","s":["FCDO advises against all but essential travel to the area between the Interstate Highway (RNIE) 2 from Tchaourou to Malanville and the Benin-Nigeria border, due to increasing criminality."]},{"k":"h","s":["Alibori and Atacora"]},{"k":"p","s":["FCDO advises against all but essential travel to the rest of the Alibori and Atacora departments, due to increasing criminality."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 118 and ask for an ambulance."]},{"k":"p","s":["Outside Cotonou, there may not be an emergency response. You are likely to have to get local advice and arrange transport to the nearest medical centre."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Benin","https://travelhealthpro.org.uk/country/27/benin#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Benin","https://travelhealthpro.org.uk/country/27/benin"],", including:"]},{"k":"li","s":["yellow fever"]},{"k":"li","s":["malaria"]},{"k":"li","s":["dengue"]},{"k":"hs","s":["HIV"]},{"k":"p","s":["The 2022 UNAIDS Report on the Global AIDS Epidemic estimated that around 72,000 adults aged 15 or over in Benin were living with HIV. The prevalence percentage was estimated at around 0.8% of the adult population compared to the prevalence percentage in adults in the UK of around 0.25%. You should exercise normal precautions to avoid exposure to HIV/AIDS."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Benin"]},{"k":"p","s":["Medical facilities are poor, particularly in rural areas. Emergency medical facilities are extremely limited. For serious medical treatment, medical evacuation is necessary. Make sure you have adequate travel health insurance and accessible funds to cover the cost of any medical treatment abroad and repatriation."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Benin","https://www.gov.uk/government/publications/benin-doctors/benin-list-of-medical-facilities"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Benin"]},{"k":"p","s":["Fire and ambulance: 118"]},{"k":"p","s":["Police: 117"]},{"k":"p","s":["Emergency response is very limited and you may need to ask for local advice to get emergency help."]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=benin"]," in Benin"]},{"k":"li","s":["dealing with a ",["death in Benin","https://www.gov.uk/government/publications/benin-bereavement-death-abroad"]]},{"k":"li","s":["being ",["arrested or imprisoned in Benin","https://www.gov.uk/government/publications/benin-legal-and-prison-systems/information-pack-for-british-nationals-arrested-or-detained-in-benin"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/benin/british-high-commission-accra"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/benin/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":15463,"change":"Updated information about applying for a visa (see 'Visa requirements' on the 'Entry requirements' page)."},"https://theconversation.com/kiwisaver-hardship-withdrawals-are-spiking-are-there-better-ways-to-deal-with-debt-296583":{"r":"conversation","at":"2026-11-17T17:03Z","sha":"b461f3b79e729f2a6939bb11e10251f3b360f12868991bc4a74cd908247e770b","read":"https://theconversation.com/kiwisaver-hardship-withdrawals-are-spiking-are-there-better-ways-to-deal-with-debt-296583","bytes":176682,"x":"fulltext v1","title":"KiwiSaver hardship withdrawals are spiking – are there better ways to deal with debt?","by":[{"n":"Victoria Stace","r":"Senior Lecturer, Faculty of Law, Te Herenga Waka — Victoria University of Wellington"}],"pub":"2026-11-15T23:19:20Z","mod":"","blocks":[{"k":"p","s":["More New Zealanders than ever are applying to take money out of their KiwiSaver accounts because of financial hardship."]},{"k":"p","s":["In the year to March 31 2025, ",["withdrawals had risen","https://www.ird.govt.nz/about-us/tax-statistics/kiwisaver/withdrawals/number"]," to NZ$443.6 million, up from $264.3 million in the previous year – a 50.8% increase."]},{"k":"p","s":["IRD figures to September 2026 show the amounts withdrawn for first home purchases still exceed the amounts withdrawn for financial hardship. But applications for financial hardship withdrawals now outnumber those for first home purchases."]},{"k":"p","s":["As one KiwiSaver provider told our research team:"]},{"k":"p","s":["The current number of [hardship] withdrawals is roughly three times what we had pre-COVID. This is really high numbers of people. This is just a massive expansion of poverty."]},{"k":"p","s":[["FinCap","https://fincap.org.nz/"],", a charitable trust that supports financial mentors helping people manage their personal finances, asked Victoria University of Wellington to look at ways people seeking a financial hardship withdrawal could keep their money in KiwiSaver."]},{"k":"p","s":["The researchers spoke to financial mentors (who provide free support to individuals with unmanageable debt), ",["Debtfix","https://www.debtfix.co.nz/"]," (which also provides assistance to people with debt), KiwiSaver providers and the Retirement Commission."]},{"k":"p","s":["Those working in the sector agree the level of hardship withdrawal applications – one in eight clients according to the mentors we spoke to – is a symptom of the financial stress New Zealanders are facing."]},{"k":"p","s":["However, ",["our report","https://fincap.org.nz/home/blog/2026/vuw-report-on-kiwisaver-hardship-withdrawals-released"]," also suggests there are ways to help people keep money in their KiwiSaver accounts – without simply making it harder to make withdrawals."]},{"k":"h","s":["‘Sidecar’ accounts for emergencies"]},{"k":"p","s":["Providing financial mentoring expertise to anyone making a withdrawal application would allow people to explore all their options before opting to take money out of their account."]},{"k":"p","s":["Financial mentors can also assist people facing unmanageable debt to negotiate with creditors, access government assistance or even go through an insolvency procedure to clear debt."]},{"k":"p","s":["One suggestion was the establishment of a centralised hardship application assessment and support “clearing house”."]},{"k":"p","s":["This could be staffed by mentors, specialist debt management organisations and other support services to assess people’s situation before any formal application was made."]},{"k":"p","s":["The report also recommends investigating and potentially trialling “sidecar” savings accounts linked to KiwiSaver. These would help members build emergency savings which could be accessed in times of hardship while leaving the rest of their KiwiSaver balance intact."]},{"k":"p","s":["The research identified significant variation between KiwiSaver providers’ hardship application processes, forms and communication. As one mentor said about their clients in prison who were applying for a hardship withdrawal:"]},{"k":"p","s":["They’re generally asking for the minimum, around $70 a week for 13 weeks, for extra food, toiletries and similar expenses. Some are getting approved, while others aren’t."]},{"k":"p","s":["The variation means having to tailor applications for each provider, which can be difficult and time consuming."]},{"k":"p","s":["It can be too easy with some providers, but with others it’s absolutely like you’re tearing your hair out trying to get one approved."]},{"k":"h","s":["Impact of election result"]},{"k":"p","s":["The report recommends government agencies such as the Retirement Commission and IRD work with KiwiSaver providers to gather more information about hardship withdrawals and standardise processes."]},{"k":"p","s":["More generally, the research found little recognition of how the rise in harship applications is adding to workloads in an already underfunded financial mentoring sector."]},{"k":"p","s":["FinCap has been advocating for sustainable funding for financial mentors and is now ",["organising a petition","https://fincap.org.nz/home/blog/2026/sign-our-petition-calling-for-sustainable-funding-for-financial-mentors"]," to government."]},{"k":"p","s":["In the meantime, the final election result will have an impact."]},{"k":"p","s":["Another National-led coalition government will likely to see ",["KiwiSaver contributions become compulsory","https://www.national.org.nz/policies/kiwisaver"]," for employers and employees. Labour is also promising to make ",["employer contributions compulsory","https://www.labour.org.nz/election-policy-pages/kiwisaver/"],", and both major parties intend to increase contribution rates."]},{"k":"p","s":["The Opportunity Party’s “KiwiSaver 2.0” proposal – part of a wider ",["tax reset","https://cdn.opportunity.org.nz/documents/policy/Opportunity%20Policy%20-%20Tax%20Reset.pdf"]," – is more drastic, including a compulsory scheme with no hardship withdrawals allowed."]},{"k":"p","s":["If a tougher savings model is introduced, it will bring the debate about hardship withdrawals into sharper focus. It is important we balance the benefits of long-term savings to support the future interests of KiwiSaver members with some allowance for withdrawals to meet present hardship."]}],"chars":4413},"https://www.gov.uk/foreign-travel-advice/new-zealand":{"r":"govuk","at":"2026-11-17T17:18Z","sha":"c33a56e860c0c65a267078d3925a53a3eb6c522afdbcbd9d97ac944895421d30","read":"https://www.gov.uk/api/content/foreign-travel-advice/new-zealand","bytes":63105,"x":"fulltext v1","title":"New Zealand travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-01-18T00:00:00+00:00","mod":"2026-03-19T14:06:12+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["This travel advice page covers New Zealand. See separate ",["travel advice for Cook Islands, Tokelau and Niue","https://www.gov.uk/foreign-travel-advice/cook-islands-tokelau-and-niue"],"."]},{"k":"h","s":["Global travel impacts due to escalation in the Middle East"]},{"k":"p","s":["Escalation in the Middle East has caused widespread travel disruption, including airspace closures, delayed and cancelled flights."]},{"k":"p","s":["Your travel plans may be affected, even if your destination is not in the Middle East. Before you travel:"]},{"k":"li","s":["check travel advice for any countries or territories you are transiting through"]},{"k":"li","s":["check for the latest updates from your airline or tour operator"]},{"k":"li","s":["review your travel insurance policy for coverage"]},{"k":"li","s":["monitor local and international media for the latest information and sign up for travel advice email alerts"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/new-zealand/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of New Zealand’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in New Zealand set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["New Zealand High Commission in the UK","https://www.mfat.govt.nz/en/countries-and-regions/europe/united-kingdom/new-zealand-high-commission/"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter New Zealand, your passport must have an ‘expiry date’ at least 3 months after the day you plan to leave."]},{"k":"p","s":["If you’re travelling through another country on your way to or from New Zealand, check the entry requirements for that country. Many countries require at least 6 months validity on your passport. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can visit New Zealand without a visa for up to 6 months. However you do need a New Zealand Electronic Travel Authority (NZeTA)."]},{"k":"p","s":["At New Zealand border control, you will also need to show:"]},{"k":"li","s":["proof of a return or onward ticket"]},{"k":"li","s":["proof that you have enough money for your stay"]},{"k":"p","s":["Check the full criteria for visa-free entry on ",["New Zealand Immigration","https://www.immigration.govt.nz/new-zealand-visas/visas/visa/visa-waiver"],"."]},{"k":"p","s":["New Zealand has strict immigration rules, particularly on employment. You must have a visa to work or study in New Zealand."]},{"k":"p","s":["Check the visa options and costs on ",["New Zealand Immigration","https://www.immigration.govt.nz/new-zealand-visas"],"."]},{"k":"p","s":["To extend your visa, first check your visa expiry date on the New Zealand ",["Visa Verification Service","https://www.immigration.govt.nz/about-us/our-online-systems/visa-verification-service"],". See ",["how to apply for a visa extension","https://www.immigration.govt.nz/new-zealand-visas/already-have-a-visa/my-situation-has-changed"],"."]},{"k":"hs","s":["New Zealand Electronic Travel Authority (NZeTA)"]},{"k":"p","s":["If you are entering without a visa, you need a ",["New Zealand Electronic Travel Authority (NZeTA)","https://www.immigration.govt.nz/new-zealand-visas/apply-for-a-visa/about-visa/nzeta"]," before you travel. You will also need to pay an ",["International Visitor Conservation and Tourism Levy","https://www.immigration.govt.nz/new-zealand-visas/preparing-a-visa-application/your-journey-to-new-zealand/before-you-travel-to-new-zealand/paying-ivl"]," when you apply."]},{"k":"p","s":["Allow up to 72 hours for it to be processed. Your NZeTA is valid for up to 2 years."]},{"k":"hs","s":["Travelling through New Zealand"]},{"k":"p","s":["You will need to get a NZeTA before you travel if you are travelling through New Zealand to another country."]},{"k":"p","s":["In most cases, transit passengers must hold an ",["NZeTA or transit NZeTA","https://www.immigration.govt.nz/new-zealand-visas/apply-for-a-visa/about-visa/nzeta"]," before travel."]},{"k":"h","s":["New Zealand Traveller Declaration"]},{"k":"p","s":["Everyone travelling into New Zealand needs to complete a New Zealand Traveller Declaration (NZTD). It is free and you can use the ",["online form","https://app.travellerdeclaration.govt.nz/#/"]," or the ",["NZTD app","https://www.travellerdeclaration.govt.nz/nztd-app/"],". There is a paper declaration form for travellers who cannot complete it online."]},{"k":"p","s":["Your declaration is linked to your passport and is checked when you arrive at the e-Gate or by a border officer."]},{"k":"hs","s":["Travelling by air"]},{"k":"p","s":["The earliest you can submit your declaration is 24 hours before you start your trip to New Zealand. It needs to be submitted by the time you reach passport control in New Zealand."]},{"k":"p","s":["If you are travelling on a domestic flight, familiarise yourself with security procedures, you can ",["read information on these from the New Zealand government","https://www.aviation.govt.nz/passenger-information/what-to-expect-at-the-airport/common-questions-from-passengers/#:~:text=Regional%20flights%20with%20planes%20that,AvSec%20(Aviation%20Security%20Service)."],"."]},{"k":"hs","s":["Travelling by sea"]},{"k":"p","s":["The earliest you can submit your declaration is 24 hours before departing the vessel’s last foreign port. It needs to be submitted by the time the vessel has arrived at its first port in New Zealand."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s New Zealand guide","https://travelhealthpro.org.uk/country/162/new-zealand#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about goods you can take into or out of New Zealand. It is illegal to import most food products. You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"p","s":["Some products, including wood and leather products, golf clubs, tents and fishing equipment, can carry harmful pests or diseases. Check ",["what items you are permitted to bring into New Zealand","https://www.mpi.govt.nz/bring-send-to-nz/bringing-and-posting-items-to-nz/check-if-you-can-bring-or-send-an-item-to-nz/"],". If in doubt, declare items to a Biosecurity New Zealand official or dispose of them in one of the marked bins available at the airport."]},{"k":"p","s":["If you break any of these rules you could get a fine of up to 100,000 New Zealand dollars or a prison sentence."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in New Zealand"]},{"k":"p","s":["Terrorist attacks in New Zealand cannot be ruled out."]},{"k":"h","s":["Crime"]},{"k":"p","s":["Crime levels are generally low, but street crime happens in major towns and cities. Thieves may target unattended vehicles, especially hire cars and camper vans in major tourist areas."]},{"k":"p","s":["You should:"]},{"k":"li","s":["avoid leaving possessions in unattended vehicles even if out of sight"]},{"k":"li","s":["not leave valuables in hotel rooms"]},{"k":"li","s":["use the hotel safe if possible"]},{"k":"li","s":["keep passports, travellers cheques and credit cards separate"]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Importing illegal drugs could result in a prison sentence of up to 12 years."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["New Zealand has an established tradition of tolerance towards same-sex relations, but there are still isolated incidents of homophobia-related crimes. LGBT+ travellers should be aware of local sensitivities, particularly when visiting rural areas. Read more ",["advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"hs","s":["Extreme sports"]},{"k":"p","s":["British nationals have been involved in tragic accidents while doing extreme sports activities. If you’re taking part in extreme sports, check that:"]},{"k":"li","s":["the company is well established"]},{"k":"li","s":["your insurance covers you"]},{"k":"hs","s":["Visiting remote areas"]},{"k":"p","s":["If you are planning to visit a remote area, check with the local tourist authorities for advice. To find out more information about being prepared, check:"]},{"k":"li","s":[["New Zealand’s Department of Conservation","https://www.doc.govt.nz/parks-and-recreation/know-before-you-go/"]]},{"k":"li","s":[["AdventureSmart","https://www.adventuresmart.nz/"]," which is managed by the New Zealand Search and Rescue Council (NZSAR)"]},{"k":"p","s":["Leave details of your itinerary with family or friends. Weather conditions can quickly become dangerous in some coastal and exposed areas. Monitor regional weather forecasts."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in New Zealand, see information on ",["driving abroad","https://www.gov.uk/driving-abroad"]," and read the Road Code. It lists driving regulations and other legal requirements you need to be aware of."]},{"k":"p","s":["You can use a UK photocard driving licence to drive in New Zealand for up to 18 months. You can ",["exchange an old-style paper licence","https://www.gov.uk/exchange-paper-driving-licence"]," if you need to."]},{"k":"p","s":["Highways can be narrow, winding and hilly. Car rental companies should provide you with information, or read ",["what’s different about driving in New Zealand","https://www.nzta.govt.nz/safety/visiting-new-zealand/"],"."]},{"k":"hs","s":["Motor vehicle insurance"]},{"k":"p","s":["Hire car companies will arrange your insurance, but if you are driving a private vehicle you must get insurance, including accident cover. Accident victims do not have a legal right to sue a third party. The ",["Accident Compensation Commission (ACC)","https://www.acc.co.nz/"]," helps pay for local care if you’re injured. However, delayed travel or loss of income in a third country is not covered."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"p","s":["Natural disasters can happen in New Zealand. If there is a disaster, follow the advice of the local authorities and the ",["National Emergency Management Agency","https://www.civildefence.govt.nz/"],". For more information, see the government’s ",["Get Ready","https://getready.govt.nz/"]," website."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["New Zealand is in a major earthquake zone. Tsunamis can happen along the coastlines. You should:"]},{"k":"li","s":["familiarise yourself with safety procedures. In New Zealand advice in the event of an earthquake is to ‘Drop, Cover, Hold’"]},{"k":"li","s":["take note of instructions in hotel rooms and public areas"]},{"k":"li","s":["find and check your local emergency services social media pages"]},{"k":"li","s":["monitor any warnings or updates from the ",["National Emergency Management Agency","https://www.civildefence.govt.nz/"]]},{"k":"p","s":["For more information about what to do before, during and after an earthquake, see the New Zealand government’s ",["Get Ready advice for earthquakes","https://getready.govt.nz/emergency/earthquakes/"],"."]},{"k":"p","s":["If there is a tsunami warning, the Local Civil Defence Emergency Management Groups will have tsunami evacuation zone maps and advice. Familiarise yourself with local arrangements from New Zealand’s ",["National Emergency Management Agency","https://www.civildefence.govt.nz/get-ready/get-tsunami-ready/tsunami-evacuation-zones"],"."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["Flooding and landslides can happen, resulting in road closures and infrastructure damage."]},{"k":"hs","s":["Volcanic eruptions"]},{"k":"p","s":["There are several active volcanoes on the North Island of New Zealand. Get local advice about where there might be volcanic activity."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 111 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for New Zealand","https://travelhealthpro.org.uk/country/162/new-zealand#Vaccine_Recommendations"]]},{"k":"li","s":["where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in New Zealand","https://travelhealthpro.org.uk/country/162/new-zealand"]]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"p","s":["You must declare any prescription medicines on your passenger arrival card. All products containing codeine are classified as prescription-only medication (a controlled drug). You can import controlled drugs for personal use, but you must declare them on arrival to the Customs Service and provide evidence that they are for personal use."]},{"k":"p","s":["See ",["New Zealand Customs","https://www.health.govt.nz/our-work/regulation-health-and-disability-system/medicines-control/bringing-medicines-new-zealand"]," for more information on restrictions on medication."]},{"k":"h","s":["Healthcare in New Zealand"]},{"k":"p","s":["British nationals who live in the UK and who are on a short-term visit to New Zealand are eligible for urgent healthcare treatment. See the ",["reciprocal health agreement with New Zealand","https://www.tewhatuora.govt.nz/our-health-system/eligibility-for-publicly-funded-health-services/reciprocal-health-agreements#summaries"]," for more details. This agreement does not extend to routine, non-emergency medical treatment including prescriptions."]},{"k":"p","s":["You can call ",["Healthline for free medical advice","https://info.health.nz/services-support/healthline"]," (24 hours)."]},{"k":"p","s":["FCDO has a ",["list of medical providers in New Zealand","https://www.gov.uk/government/publications/new-zealand-list-of-medical-facilities-and-funeral-directors"],"."]},{"k":"p","s":["There is also ",["guidance on healthcare if you’re living in New Zealand","https://www.gov.uk/guidance/living-in-new-zealand"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in New Zealand"]},{"k":"p","s":["Telephone: 111 (ambulance, fire, police)"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=New%20Zealand"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=New%20Zealand"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find?country=New%20Zealand&serviceType=translatorsInterpreters"]," in New Zealand"]},{"k":"li","s":["dealing with a ",["death in New Zealand","https://www.gov.uk/government/publications/new-zealand-bereavement-pack-information"]]},{"k":"li","s":["being ",["arrested or imprisoned in New Zealand","https://www.gov.uk/government/publications/new-zealand-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/new-zealand/british-high-commission-wellington"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/new-zealand/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in New Zealand","https://www.gov.uk/government/publications/overseas-business-risk-new-zealand"]," on how to manage political, economic, and business security-related risks."]}],"chars":13923,"change":"Updated information about global travel impacts due to escalation in the Middle East (‘Warnings and insurance’ page)."},"https://theconversation.com/a-decade-on-somalias-federal-pact-benefits-elites-and-al-shabaab-but-it-fails-the-people-291192":{"r":"conversation","at":"2026-11-17T17:18Z","sha":"9997bea189dfc1d83e884b29e8f87546025b6a407e157eba48bf3b9541bf28d4","read":"https://theconversation.com/a-decade-on-somalias-federal-pact-benefits-elites-and-al-shabaab-but-it-fails-the-people-291192","bytes":182173,"x":"fulltext v1","title":"A decade on, Somalia’s federal pact benefits elites and al-Shabaab – but it fails the people","by":[{"n":"Nisar Majid","r":"Research associate, London School of Economics and Political Science"}],"pub":"2026-09-21T13:48:29Z","mod":"","blocks":[{"k":"p","s":["The federal government of Somalia was established in 2013 after ",["years of peace and reconciliation talks","https://cdn.odi.org/media/documents/11466.pdf"],", held in the context of a ",["famine","https://www.bbc.co.uk/news/world-africa-22380352"]," in 2011 and the ",["rise","https://academic.oup.com/book/26104/chapter-abstract/194094385?redirectedFrom=fulltext"]," of militant Islam in the form of al-Shabaab. It was the first permanent central government in Somalia since the start of the civil war in 1991."]},{"k":"p","s":["Peace agreements and political settlements do not necessarily transform a country’s development prospects. In Somalia and the region, conflict and political instability continue. The federal government still has ",["limited reach and authority","https://issblog.nl/2024/10/01/in-this-blog-ahmed-sh-ibrahim-and-nisar-majid-consider-how-somalias-joining-of-the-un-security-council-at-a-time-when-its-nationally-recognised-government-controls-only-a-portions-of-its-t/"],", and al-Shabaab is ",["still entrenched","https://warontherocks.com/flailing-state-the-resurgence-of-al-shabaab-in-somalia/"],"."]},{"k":"p","s":["Political elites at federal and state levels are seen to be corrupt and at odds with each other."]},{"k":"p","s":["I have ",["studied Somalia’s political economy for over 20 years","https://peacerep.org/about/countries/somalia/"],". In 2016 I co-authored the book ",["Famine in Somalia","https://academic.oup.com/book/12643"],", and since 2018 I have led two ",["research programmes","https://peacerep.org/about/countries/"]," examining Somalia’s persistent conflict and political instability."]},{"k":"p","s":["Read more: ",["South Sudan at 15: how the political elite have found a way to profit from peace as well as war","https://theconversation.com/south-sudan-at-15-how-the-political-elite-have-found-a-way-to-profit-from-peace-as-well-as-war-285846"]]},{"k":"p","s":["Over the past three years, my work with the PeaceRep Somalia programme at the London School of Economics has sought to deepen understanding of this situation in order to better inform policy responses. The work brings together researchers based inside and outside the country. We have conducted several hundred interviews across the country and in the Somali diaspora, and analysed our data according to themes."]},{"k":"p","s":["Two themes stand out:"]},{"k":"li","s":["checkpoint governance, or the control of movement – goods and people – by different political authorities"]},{"k":"li","s":["the control, mismanagement and manipulation of international aid."]},{"k":"p","s":["We found that political elites and their business allies at both federal and member state levels benefit from corruption associated with international assistance. They also benefit from the rents generated at the various “chokepoints” (seaports and road-based checkpoints) along Somalia’s transport corridors."]},{"k":"p","s":["At the same time, the international community advances its own priorities on counterterrorism, anti-migration, development and humanitarian objectives. And al-Shabaab taxes, regulates and extracts from the entire complex."]},{"k":"p","s":["I argue that Somalia has settled into a situation which brings questionable benefits to the majority of the public, exploits displaced people, and positions al-Shabaab as a credible alternative to the official government."]},{"k":"h","s":["Somalia’s chokepoints"]},{"k":"p","s":["Somalia has the second longest coastline in Africa – about 3,000km. The country’s major and minor seaports and landing beaches act as both avenues and chokepoints for international trade. The main export is livestock. Imports include food, electrical and electronic goods, clothes and construction materials."]},{"k":"p","s":["This ",["trade infrastructure links markets in the Gulf and Asia with those in the Horn and east Africa","https://hurstpublishers.com/book/trade-makes-states/"],". Taxes are extracted at the entry points – including Berbera, Bosasso, Mogadishu and Kismayo ports – and on the interior roads. These taxes, formal and informal, make up a big part of the revenue generated in the country."]},{"k":"p","s":["The recipients of these revenues include the federal government, the more autonomous federal member states – notably Jubbaland and Puntland – and al-Shabaab. This enables all these players to continue as they are."]},{"k":"p","s":["Read more: ",["Somalia at 65: what’s needed to address its dismal social development indicators","https://theconversation.com/somalia-at-65-whats-needed-to-address-its-dismal-social-development-indicators-258307"]]},{"k":"p","s":["Our research has shown how control over ",["chokepoints has been central to political power in Somalia","https://peacerep.org/2026/03/17/checkpoints-regional-entanglements-and-political-entrepreneurs/"],". It also shapes alliances between local elites and external actors like Ethiopia and Kenya."]},{"k":"p","s":["Somalia’s business-political elites and al-Shabaab continue to profit from the way things are. Meanwhile large proportions of the population see little benefit or, in the case of internally displaced people, see aid diverted."]},{"k":"h","s":["Manipulation of external aid"]},{"k":"p","s":["Somalia receives significant amounts of international aid for humanitarian, development and security needs. Since 2010, Overseas Development Aid has averaged US$1.6 billion annually, reaching approximately ",["US$2.5 billion in 2024","https://mof.gov.so/sites/default/files/Publications/ODA%20Cuts%20to%20Somalia%20-%20Policy%20Paper%20%28Volume%20I%29.pdf"],". The aid is channelled through project contracts – typically for hiring staff, construction, security, vehicle hire, offices and accommodation. All of these are highly ",["susceptible to aid diversion and corruption","https://www.transparency.org/en/publications/collective-resolution-to-enhance-accountability-and-transparency-in-emergen"],"."]},{"k":"p","s":["One of the worst forms is the ",["exploitation of internally displaced people","https://www.thenewhumanitarian.org/opinion/2023/10/26/powerful-networks-impose-taxes-aid-somalia-its-time-end"],", who are some of the main recipients of assistance. This is ",["typically","https://www.nrc.no/resources/reports/gatekeeping-in-somalia"]," carried out by chains of “gatekeepers” who claim some of the humanitarian cash to allow access to camps. Religious leaders have ",["spoken out","https://peacerep.org/2025/01/27/humanitarian-aid-in-baidoa-religious-leaders-speak-out/"]," against this practice."]},{"k":"p","s":["Development aid, which supports a range of activities from institution building to public services, ",["is no less subject to capture","https://peacerep.org/publication/mid-term-corruption-and-international-engagement/"]," and abuse but is much less publicly exposed. This is partly because development actors are much better able to hide their dirty laundry. This is particularly important currently as, with the global reductions in humanitarian aid, the World Bank continues to run a large programme supporting state institutions and social protection. The security sector is even more opaque but ",["just as susceptible to elite capture","https://www.lse.ac.uk/ideas/Assets/Documents/Conflict-Research-Programme/crp-memos/Norman-private-military-mogadishu-final.pdf"],"."]},{"k":"p","s":["The core issue for me is the ",["lack of acknowledgement","https://peacerep.org/2023/08/07/corruption-accountability-somalia/"]," that aid is diverted systematically."]},{"k":"p","s":["The result is that external aid givers advance their own priorities but do not fully acknowledge or systematically address their role in the diversion of resources that sustain this predatory system."]},{"k":"p","s":["The losers in this arrangement are the general population. Many see ",["al-Shabaab as a credible alternative to the official government leadership","https://peacerep.org/2025/04/16/a-seat-at-the-un-security-council-a-state-on-the-brink/"],", incumbent or opposition."]},{"k":"h","s":["What should be done?"]},{"k":"p","s":["International donors must not just engage with elites. They must identify, engage with and support inclusive Somali-led dialogue processes. Engagement must create space for diverse voices and interests across society (including al-Shabaab). It must hear what civic networks, women’s groups, business communities and religious scholars have to say."]},{"k":"p","s":["Read more: ",["Al-Shabaab in Somalia has resisted military force: now is the time for a new strategy","https://theconversation.com/al-shabaab-in-somalia-has-resisted-military-force-now-is-the-time-for-a-new-strategy-194295"]]},{"k":"p","s":["The humanitarian system is in a global reset. This is a process of reform driven by ",["aid cuts","https://www.unocha.org/news/humanitarian-reset-10-march-2025"],". In Somalia, this reset must include ",["acknowledgement of systemic barriers to change and address some of its perverse internal incentives","https://peacerep.org/wp-content/uploads/2024/04/Time-for-Change-The-Normalization-of-Corruption-and-Diversion-in-the-Humanitarian-Sector-DIGITAL.pdf"],", which continue to enable corruption and aid diversion."]}],"chars":6251},"https://theconversation.com/backlash-against-data-centers-helped-democrats-win-the-midterms-297020":{"r":"conversation","at":"2026-11-24T14:28Z","sha":"c26f115336bae6914c3bbadcf5448bc5b213a5830a8650e74ab6d8faee24d07f","read":"https://theconversation.com/backlash-against-data-centers-helped-democrats-win-the-midterms-297020","bytes":183199,"x":"fulltext v1","title":"Backlash against data centers helped Democrats win the midterms","by":[{"n":"Jesse Usher Barrett","r":"Graduate Poll Fellow in Political Science, UMass Amherst"},{"n":"Jesse Rhodes","r":"Associate Professor of Political Science, UMass Amherst"},{"n":"Tatishe Nteta","r":"Provost Professor of Political Science, UMass Amherst"},{"n":"Tim Komatsu","r":"PhD student in Political Science, UMass Amherst"}],"pub":"2026-11-24T13:11:51Z","mod":"","blocks":[{"k":"p","s":["The ",["2026 midterm elections","https://theconversation.com/topics/2026-us-midterms-194085"]," that ",["swept Democrats into power","https://www.pbs.org/newshour/politics/democrats-usher-in-a-new-era-with-their-resounding-sweep-of-the-house-and-the-senate"]," in Congress and state legislatures also delivered a stunning ",["rebuke to the artificial intelligence industry","https://www.nytimes.com/2026/11/04/technology/midterm-elections-ai-data-centers.html"],"."]},{"k":"p","s":["Ballot measures that limited the ",["construction of data centers","https://theconversation.com/voters-rejected-data-centers-in-dozens-of-communities-fueling-the-narrative-that-opposition-to-the-ai-infrastructure-contributed-to-the-2026-blue-wave-295950"]," – from California to Kansas to North Dakota – were ",["approved by voters in 40 of 41 instances","https://news.ballotpedia.org/2026/11/06/voters-favored-limiting-data-center-development-in-40-of-41-local-ballot-measures-on-nov-3/"],". ",["These measures","https://ballotpedia.org/Data_center-related_ballot_measures,_2026"]," included ",["the Kansas prohibition","https://ballotpedia.org/Emporia,_Kansas,_Prohibit_Tier_2_and_Tier_3_Battery_Energy_Storage_Systems_Initiative_(November_2026)"]," on construction of a type of battery energy storage system, ",["a 180-day moratorium on data centers","https://www.newscentermaine.com/article/news/politics/elections/maine-towns-vote-overwhelmingly-restrict-data-center-growth/97-f8c1d051-71cc-40ac-af42-77f651b3c115"]," in Maine, and the outright ",["ban on data center construction in Ohio","https://www.wsj.com/livecoverage/midterm-election-results-2026-latest-updates/card/voters-rejecting-data-center-development-in-ballot-measures-G2USC5DVgAzw4W8aODHa"],"."]},{"k":"p","s":["Drawing on recent survey data, we suggest that the Democratic sweep and the nationwide rejection of data centers are related. ",["Republicans’ connections with an unpopular AI industry","https://nymag.com/intelligencer/article/republicans-are-lost-in-the-ai-wilderness.html"]," may have contributed to their poor showing at the polls."]},{"k":"h","s":["Bipartisan rejection"]},{"k":"p","s":[["We are survey researchers","https://www.umass.edu/poll/"],". Our ",["August 2026 survey","https://www.umass.edu/news/article/just-1-9-americans-support-ai-data-center-construction-their-local-communities"]," of a nationally representative sample of 1,000 American adults shows that opposition to data centers is widespread."]},{"k":"p","s":["The survey shows that 65% of Americans oppose the construction of data centers in their communities. This opposition is bipartisan, with 76% of Democrats, 67% of independents and 52% of Republicans opposed to the sites."]},{"k":"p","s":["To better understand the sources of this opposition, we asked respondents to explain it in their own words. Twenty-eight percent of respondents voiced concerns about the ",["negative environmental impact of data centers","https://environment.yale.edu/news/article/data-centers-urban-heat-and-ai-growth"],". One respondent stated: “Draining our water reserves significantly with a data center would be catastrophic to our region.”"]},{"k":"p","s":["Some respondents, 15%, also expressed concerns about data centers’ negative impact on their quality of life. For example, one respondent said: “Noise issues, energy issues and visual site are three issues that are major concerns for a AI data center to be in the area I live in.”"]},{"k":"p","s":["Ten percent of respondents singled out the centers’ connection to ",["increased utility costs","https://www.forbes.com/sites/maryroeloffs/2026/11/02/data-centers-are-key-issue-in-midterm-battleground-states-as-household-electric-rates-soar/"],". One respondent said that “ever since a data center has been built in my local area the prices of water and electricity have more than doubled.”"]},{"k":"p","s":["Finally, 13% of respondents expressed a broad distrust of AI and the industry itself, with one stating, “I think that AI needs to be better regulated and a lot more developed and proven safe before any massive full scale deployment.”"]},{"k":"h","s":["A winning issue"]},{"k":"p","s":["Despite ",["mounting public opposition to data centers","https://news.gallup.com/poll/709772/americans-oppose-data-centers-area.aspx"],", ",["President Donald Trump expressed strong support","https://abcnews.com/Politics/data-reign-trump-stands-firmly-controversial-data-centers/story?id=136092127"]," for data center construction before Election Day. He said that ",["if Americans want to live","https://time.com/article/2026/10/01/donald-trump-2026-interview-transcript/"]," in “crime-infested areas” and “squalor,” they should not have a data center. Days after the midterms, ",["Trump threatened to penalize U.S. companies","https://apnews.com/article/trump-artificial-intelligence-data-centers-f1ac03b73d13445400eeed8631d9d879"]," that build data centers overseas."]},{"k":"p","s":["As widespread opposition to data centers grew through 2026, Republican congressional candidates increasingly had to weigh loyalty to Trump against ",["local backlash","https://www.cbsnews.com/news/data-center-boom-republicans-2026-midterm-elections/"],". As Election Day neared, many Republican candidates had distanced themselves from ",["unrestricted data center construction","https://www.politico.com/news/2026/11/04/data-centers-are-midterms-big-loser-01145171"],"."]},{"k":"p","s":["In contrast, many ",["Democrats made opposition to data centers","https://www.politico.com/news/2026/09/06/democrats-hone-midterm-attacks-data-centers-01066167"]," an important theme of their campaigns."]},{"k":"p","s":["Our poll suggests that these efforts may have resonated with voters."]},{"k":"p","s":["Among Americans who expressed opposition to data centers, 48% indicated they would support the local Democratic candidate in the U.S. House of Representatives, compared to 25% for the Republican candidate. And 47% of those living in states that held a Senate election were planning on voting for the Democratic candidate, while 28% planned to vote for the Republican Senate candidate."]},{"k":"p","s":["Even taking partisanship, ideology and demographic characteristics into account, opposition to data centers was associated with an intention to support Democratic House and Senate candidates."]},{"k":"p","s":["Given widespread public concern about data center construction, Democrats have electoral incentives to make AI regulation a part of their legislative agenda in the new Congress. Whether or not they enact new legislation, popular opposition to data centers is unlikely to abate anytime soon."]}],"chars":3955}};
